-- Phase 68: governed operational knowledge base. Documents, Learning, Tasks, Communications, Search and Runbooks remain source systems.
-- quality: allow-nonconcurrent-index reason=new-empty-phase68-tables
create extension if not exists vector with schema extensions;
create schema if not exists knowledge_private;
revoke all on schema knowledge_private from public,anon,authenticated;

alter table public.plans add column if not exists knowledge_base_enabled boolean not null default true,add column if not exists knowledge_semantic_search_enabled boolean not null default false,add column if not exists knowledge_ai_assistant_enabled boolean not null default false,add column if not exists knowledge_offline_enabled boolean not null default true,add column if not exists knowledge_customer_safe_content_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists knowledge_base_enabled boolean not null default true,add column if not exists knowledge_semantic_search_enabled boolean not null default false,add column if not exists knowledge_ai_assistant_enabled boolean not null default false,add column if not exists knowledge_offline_enabled boolean not null default true,add column if not exists knowledge_customer_safe_content_enabled boolean not null default false;

create table public.knowledge_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{knowledge:view}',scope_type text not null default 'store' check(scope_type in('organization','brand','region','store','role','team')),scope_ids text[] not null default '{}',active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(organization_id,user_id));
create table public.knowledge_review_policies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,article_type text,critical_only boolean not null default false,review_cycle_days integer not null check(review_cycle_days between 1 and 3650),approval_required boolean not null default true,segregation_required boolean not null default false,active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(organization_id,name));
create table public.knowledge_articles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,article_type text not null check(article_type in('sop','faq','guide','troubleshooting','playbook','policy','reference','script','how_to','runbook_reference','custom')),title text not null,summary text,status text not null default 'draft' check(status in('draft','review','published','scheduled','deprecated','archived')),owner_user_id uuid references auth.users(id),scope_type text not null check(scope_type in('organization','brand','region','store','role','team','system')),scope_id text,confidentiality text not null default 'normal' check(confidentiality in('normal','restricted','confidential')),audience text not null default 'internal_only' check(audience in('internal_only','agent_safe','customer_safe')),current_version integer not null default 0,current_version_id uuid,review_policy_id uuid references public.knowledge_review_policies(id),review_cycle_days integer,review_status text not null default 'current' check(review_status in('current','review_due','overdue','source_stale')),next_review_at timestamptz,critical boolean not null default false,corporate_locked boolean not null default false,effective_from timestamptz,effective_until timestamptz,replaced_by_article_id uuid references public.knowledge_articles(id) on delete set null,offline_policy text not null default 'allowed' check(offline_policy in('allowed','essential','blocked')),keywords text[] not null default '{}',created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_at timestamptz,archived_at timestamptz,check(not critical or owner_user_id is not null),check(effective_until is null or effective_from is null or effective_until>effective_from));
create table public.knowledge_article_versions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,article_id uuid not null references public.knowledge_articles(id) on delete restrict,version integer not null,title text not null,content text not null,content_format text not null default 'safe_markdown' check(content_format in('safe_markdown','safe_rich_text')),change_summary text not null,change_type text not null default 'minor' check(change_type in('minor','major')),source_refs jsonb not null default '[]',content_hash text not null,workflow_status text not null default 'draft' check(workflow_status in('draft','review','approved','published','superseded','rejected')),created_by uuid not null references auth.users(id),reviewed_by uuid references auth.users(id),approved_by uuid references auth.users(id),approval_id uuid references public.internal_approvals(id),created_at timestamptz not null default now(),reviewed_at timestamptz,approved_at timestamptz,published_at timestamptz,unique(article_id,version),unique(article_id,content_hash),check(content!~*'<\s*(script|iframe|object|embed|form)|javascript:|on\w+\s*='));
alter table public.knowledge_articles add constraint knowledge_articles_current_version_fk foreign key(current_version_id)references public.knowledge_article_versions(id)on delete set null;
create table public.knowledge_source_references(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,article_version_id uuid not null references public.knowledge_article_versions(id) on delete cascade,source_type text not null check(source_type in('compliance_document','internal_document','asset_document','supplier_manual','incident_runbook','knowledge_article','configured_regulation','course','other')),source_id text not null,section_reference text,required boolean not null default false,metadata jsonb not null default '{}',validity_status text not null default 'unknown' check(validity_status in('valid','expiring','expired','deprecated','unknown')),last_checked_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(article_version_id,source_type,source_id,section_reference));
create table public.knowledge_sop_profiles(article_id uuid primary key references public.knowledge_articles(id) on delete cascade,procedure_owner uuid not null references auth.users(id),departments text[] not null default '{}',roles text[] not null default '{}',estimated_duration_minutes integer,prerequisites jsonb not null default '[]',required_tools jsonb not null default '[]',safety_notes text,related_assets uuid[] not null default '{}',related_documents uuid[] not null default '{}',related_training uuid[] not null default '{}',related_audits uuid[] not null default '{}',updated_at timestamptz not null default now());
create table public.knowledge_procedure_steps(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,article_version_id uuid not null references public.knowledge_article_versions(id) on delete cascade,step_number integer not null check(step_number>0),title text not null,instruction text not null,step_type text not null check(step_type in('instruction','check','decision','warning','escalation','action_reference')),validation_rule jsonb,related_action text references public.search_command_registry(id),branches jsonb not null default '[]',unique(article_version_id,step_number),check(jsonb_typeof(branches)='array'));
create table public.knowledge_collections(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,parent_id uuid references public.knowledge_collections(id) on delete restrict,name text not null,description text,scope_type text not null default 'organization',scope_id text,position integer not null default 100,active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(parent_id is null or parent_id<>id));
