create table public.knowledge_article_access(id uuid primary key default gen_random_uuid(),article_id uuid not null references public.knowledge_articles(id) on delete cascade,scope_type text not null check(scope_type in('organization','brand','region','store','role','team','user')),scope_id text not null,permission text not null check(permission in('view','edit','review','publish')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(article_id,scope_type,scope_id,permission));
create table public.knowledge_reviews(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,article_id uuid not null references public.knowledge_articles(id) on delete restrict,article_version_id uuid not null references public.knowledge_article_versions(id) on delete restrict,review_type text not null check(review_type in('periodic','publication','major_update','source_stale')),status text not null default 'pending' check(status in('pending','in_review','approved','changes_requested','rejected','completed')),reviewer_user_id uuid references auth.users(id),approval_id uuid references public.internal_approvals(id),classification text check(classification is null or classification in('minor','major')),notes text,due_at timestamptz,completed_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.knowledge_chunks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,article_id uuid not null references public.knowledge_articles(id) on delete cascade,article_version_id uuid not null references public.knowledge_article_versions(id) on delete cascade,chunk_index integer not null,heading text,content text not null,content_normalized text not null default '',embedding extensions.vector(384),embedding_model text,token_count integer,size_bytes integer,searchable boolean not null default true,active boolean not null default true,scope_type text not null,scope_id text,confidentiality text not null,audience text not null,fts tsvector generated always as(to_tsvector('portuguese',coalesce(heading,'')||' '||content_normalized))stored,created_at timestamptz not null default now(),unique(article_version_id,chunk_index));
create table public.knowledge_context_links(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,route_pattern text not null,module text not null,entity_type text,article_id uuid not null references public.knowledge_articles(id) on delete cascade,priority integer not null default 100,condition_definition jsonb not null default '{}',active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(organization_id,route_pattern,article_id));
create table public.knowledge_entity_links(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,article_id uuid not null references public.knowledge_articles(id) on delete cascade,entity_type text not null check(entity_type in('document','course','audit_item','audit_finding','quality_nonconformity','incident_runbook','support_article','support_ticket','asset','product','store_configuration','supplier')),entity_id text not null,relation_type text not null default 'related' check(relation_type in('source','related','procedure','manual','troubleshooting','training_source','corrective_guidance')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(article_id,entity_type,entity_id,relation_type));
create table public.knowledge_favorites(organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,article_id uuid not null references public.knowledge_articles(id) on delete cascade,created_at timestamptz not null default now(),primary key(organization_id,user_id,article_id));
create table public.knowledge_recents(organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,article_id uuid not null references public.knowledge_articles(id) on delete cascade,viewed_at timestamptz not null default now(),view_count integer not null default 1,primary key(organization_id,user_id,article_id));
create table public.knowledge_feedback(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,article_id uuid not null references public.knowledge_articles(id) on delete cascade,version integer not null,user_id uuid references auth.users(id) on delete set null,feedback_type text not null check(feedback_type in('helpful','not_helpful','outdated','unclear','missing_step','incorrect')),comment text,created_at timestamptz not null default now());
create table public.knowledge_gaps(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,query_hash text not null,suggested_topic text,occurrence_count integer not null default 1,status text not null default 'suggested' check(status in('suggested','reviewing','planned','resolved','dismissed')),owner_user_id uuid references auth.users(id),resolved_article_id uuid references public.knowledge_articles(id),first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),unique(organization_id,query_hash));
create table public.knowledge_search_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,query_hash text not null,query_length integer not null,result_count integer not null,search_mode text not null check(search_mode in('keyword','semantic','hybrid','fallback')),zero_result boolean generated always as(result_count=0)stored,opened_article_id uuid references public.knowledge_articles(id) on delete set null,latency_ms integer,created_at timestamptz not null default now(),check(query_hash~'^[a-f0-9]{64}$'));
create table public.knowledge_answer_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,question_hash text not null,retrieval_success boolean not null,citation_count integer not null default 0,refused boolean not null default false,domain_filter text,latency_ms integer,article_versions jsonb not null default '[]',created_at timestamptz not null default now());
create table public.knowledge_offline_policies(article_id uuid primary key references public.knowledge_articles(id) on delete cascade,allow_offline boolean not null default true,essential boolean not null default false,cache_ttl_hours integer not null default 168 check(cache_ttl_hours between 1 and 8760),updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table public.knowledge_cta_registry(id text primary key,label text not null,command_id text not null references public.search_command_registry(id) on delete restrict,required_permission text,risk_level text not null check(risk_level in('low','medium','high','critical')),active boolean not null default true,created_at timestamptz not null default now());
create table public.knowledge_embedding_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,article_version_id uuid references public.knowledge_article_versions(id) on delete cascade,job_type text not null check(job_type in('chunk','embed','deactivate_old_version','source_check','review_reminder','analytics')),status text not null default 'pending' check(status in('pending','processing','retrying','completed','failed','dead_letter')),idempotency_key text not null,attempts integer not null default 0,max_attempts integer not null default 5,available_at timestamptz not null default now(),locked_at timestamptz,locked_by text,last_error text,created_at timestamptz not null default now(),completed_at timestamptz,unique(organization_id,idempotency_key));
create table public.knowledge_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,article_id uuid references public.knowledge_articles(id) on delete set null,actor_user_id uuid references auth.users(id),event_type text not null,entity_type text not null,entity_id text,reason text,before_state jsonb,after_state jsonb,metadata jsonb not null default '{}',correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());

create table public.fact_knowledge_searches(organization_id uuid not null,event_id bigint not null,search_mode text not null,result_count integer not null,zero_result boolean not null,occurred_at timestamptz not null,primary key(organization_id,event_id));
