create index knowledge_articles_scope_idx on public.knowledge_articles(organization_id,scope_type,scope_id,status,updated_at desc);
create index knowledge_articles_review_idx on public.knowledge_articles(organization_id,review_status,next_review_at);
create index knowledge_versions_article_idx on public.knowledge_article_versions(article_id,version desc);
create index knowledge_chunks_scope_idx on public.knowledge_chunks(organization_id,scope_type,scope_id,confidentiality,active);
create index knowledge_chunks_fts_idx on public.knowledge_chunks using gin(fts);
create index knowledge_chunks_vector_idx on public.knowledge_chunks using hnsw(embedding extensions.vector_cosine_ops)where embedding is not null and active;
create index knowledge_feedback_article_idx on public.knowledge_feedback(article_id,created_at desc);
create index knowledge_jobs_due_idx on public.knowledge_embedding_jobs(status,available_at)where status in('pending','retrying');

create or replace function knowledge_private.collection_depth_guard()returns trigger language plpgsql security invoker set search_path='' as $$declare d integer:=0;p uuid:=new.parent_id;begin while p is not null loop d:=d+1;if d>3 then raise exception 'knowledge collection depth exceeded';end if;if p=new.id then raise exception 'knowledge collection cycle';end if;select parent_id into p from public.knowledge_collections where id=p;end loop;return new;end$$;
create trigger knowledge_collection_depth before insert or update of parent_id on public.knowledge_collections for each row execute function knowledge_private.collection_depth_guard();

create or replace function public.search_knowledge_keyword(requested_org uuid,requested_query text,requested_scope_types text[],requested_scope_ids text[],allow_confidential boolean default false,requested_limit integer default 10)returns table(article_id uuid,article_version_id uuid,chunk_id uuid,title text,article_type text,version integer,scope_type text,scope_id text,confidentiality text,heading text,snippet text,rank real)language sql stable security invoker set search_path='' as $$select a.id,v.id,c.id,a.title,a.article_type,v.version,a.scope_type,a.scope_id,a.confidentiality,c.heading,left(c.content,480),greatest(case when lower(a.title)=lower(requested_query)then 100 else 0 end,0)+ts_rank(c.fts,websearch_to_tsquery('portuguese',requested_query))from public.knowledge_chunks c join public.knowledge_articles a on a.id=c.article_id join public.knowledge_article_versions v on v.id=c.article_version_id where c.organization_id=requested_org and c.active and c.searchable and a.status='published'and a.current_version_id=v.id and(a.effective_from is null or a.effective_from<=now())and(a.effective_until is null or a.effective_until>now())and(a.confidentiality<>'confidential'or allow_confidential)and(a.scope_type in('organization','system')or(a.scope_type=any(requested_scope_types)and a.scope_id=any(requested_scope_ids)))and(c.fts@@websearch_to_tsquery('portuguese',requested_query)or a.title ilike'%'||requested_query||'%')order by 12 desc limit least(greatest(requested_limit,1),50)$$;
revoke all on function public.search_knowledge_keyword(uuid,text,text[],text[],boolean,integer)from public,anon,authenticated;grant execute on function public.search_knowledge_keyword(uuid,text,text[],text[],boolean,integer)to service_role;
create or replace function public.search_knowledge_semantic(requested_org uuid,requested_embedding extensions.vector(384),requested_scope_types text[],requested_scope_ids text[],allow_confidential boolean default false,match_threshold real default .72,requested_limit integer default 10)returns table(article_id uuid,article_version_id uuid,chunk_id uuid,title text,article_type text,version integer,scope_type text,scope_id text,confidentiality text,heading text,snippet text,similarity real)language sql stable security invoker set search_path='' as $$select a.id,v.id,c.id,a.title,a.article_type,v.version,a.scope_type,a.scope_id,a.confidentiality,c.heading,left(c.content,480),(1-(c.embedding operator(extensions.<=>) requested_embedding))::real from public.knowledge_chunks c join public.knowledge_articles a on a.id=c.article_id join public.knowledge_article_versions v on v.id=c.article_version_id where c.organization_id=requested_org and c.active and c.searchable and c.embedding is not null and a.status='published'and a.current_version_id=v.id and(a.effective_from is null or a.effective_from<=now())and(a.effective_until is null or a.effective_until>now())and(a.confidentiality<>'confidential'or allow_confidential)and(a.scope_type in('organization','system')or(a.scope_type=any(requested_scope_types)and a.scope_id=any(requested_scope_ids)))and 1-(c.embedding operator(extensions.<=>) requested_embedding)>=match_threshold order by c.embedding operator(extensions.<=>) requested_embedding limit least(greatest(requested_limit,1),50)$$;
revoke all on function public.search_knowledge_semantic(uuid,extensions.vector,text[],text[],boolean,real,integer)from public,anon,authenticated;grant execute on function public.search_knowledge_semantic(uuid,extensions.vector,text[],text[],boolean,real,integer)to service_role;

do $$declare t text;begin foreach t in array array['knowledge_member_permissions','knowledge_review_policies','knowledge_articles','knowledge_article_versions','knowledge_source_references','knowledge_sop_profiles','knowledge_procedure_steps','knowledge_collections','knowledge_article_collections','knowledge_addenda','knowledge_article_access','knowledge_reviews','knowledge_chunks','knowledge_context_links','knowledge_entity_links','knowledge_favorites','knowledge_recents','knowledge_feedback','knowledge_gaps','knowledge_search_events','knowledge_answer_events','knowledge_offline_policies','knowledge_cta_registry','knowledge_embedding_jobs','knowledge_audit_events','fact_knowledge_searches','fact_knowledge_article_views','fact_knowledge_feedback','fact_knowledge_reviews','fact_knowledge_answer_events','dim_knowledge_article','dim_knowledge_type','dim_knowledge_scope','dim_feedback_type']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('create policy %I on public.%I for all to service_role using(true)with check(true)','knowledge_service_'||t,t);end loop;end$$;

